export function pipeline(bench,c){const steps=[];if(bench==='music'){
 steps.push({label:'Input',cells:[{text:'|0⟩'},{text:'|0⟩'}]});steps.push({label:'Preparation · slider',cells:[0,1].map(q=>({text:`Ry(${(c['theta'+q]*180/Math.PI).toFixed(1)}°)`,focus:'theta'+q,kind:'slider'}))});steps.push({label:'Phase · slider',cells:[0,1].map(q=>({text:`P(${(c['phi'+q]*180/Math.PI).toFixed(1)}°)`,focus:'phi'+q,kind:'slider'}))});if(c.cnot)steps.push({label:'Preparation CNOT',cells:[{text:'● control',focus:'cnot',kind:'slider'},{text:'⊕ target',focus:'cnot',kind:'slider'}]});
 c.circuit.forEach((g,i)=>steps.push({label:'Added '+(i+1),cells:[0,1].map(q=>({text:g.type==='CNOT'?(g.q===q?'● control':'⊕ target'):['CZ','SWAP'].includes(g.type)?g.type:g.q===q?g.type+(g.angle!==undefined?' '+g.angle+'°':''):'—',gate:i,kind:'added'}))}));steps.push({label:'Measurement',cells:[0,1].map(q=>({text:c['basis'+q]+' basis',focus:'basis'+q,kind:'readout'}))});
 }else{
 if(c.densityInput)steps.push({label:'Imported effective input',cells:[{text:'ρeffective (joint)'},{text:c.densityInput.treatment==='clip'?'Declared PSD clipping':'Original valid matrix'}]});else {steps.push({label:'Local input · radius slider',cells:[0,1].map(q=>({text:`ρz(r=${c.qubits[q].radius.toFixed(2)})`,focus:'s-radius'+q,kind:'slider'}))});for(const [key,gate] of [['theta','Ry'],['phi','Rz']])steps.push({label:'Preparation · slider',cells:[0,1].map(q=>({text:`${gate}(${c.qubits[q][key].toFixed(1)}°)`,focus:'s-'+key+q,kind:'slider'}))});}
 if(c.model==='nmr')steps.push({label:'Thermal embedding',cells:[{text:'(1−ε)I/4 + ερeffective'},{text:'ε = 10⁻⁵ · physical ensemble'}]});
 const slots=[...new Set(c.circuit.map(g=>g.step))].sort((a,b)=>a-b);for(const slot of slots)steps.push({label:'Slot '+(slot+1),cells:[0,1].map(q=>{const g=c.circuit.find(g=>g.step===slot&&(g.q===q||['CNOT','CZ','SWAP','Wait'].includes(g.type)));return {text:!g?'—':g.type==='CNOT'?(g.q===q?'● control':'⊕ target'):g.type==='Wait'?'Wait '+g.ms+' ms':g.type+(g.angle!==undefined?' '+g.angle+'°':''),slot,wire:q,kind:'added'};})});
 steps.push({label:'Readout',cells:[0,1].map(q=>({text:c.readout==='both'||c.readout==='q'+q?'Ry(+90°)':'none',focus:'s-readout',kind:'readout'}))});steps.push({label:'Acquisition · physical time',cells:[{text:`FID ${c.windowMs} ms`,focus:'s-windowMs',kind:'readout'},{text:c.echo?`Xπ both @ τ=${c.tauMs} ms; echo 2τ`:'Free FID · no echo',focus:'s-echo',kind:'readout'}]});
 }return steps;}
